<?php

namespace App\Models;

use Illuminate\Database\Eloquent\Concerns\HasUuids;
use Illuminate\Database\Eloquent\Model;
use Illuminate\Database\Eloquent\Relations\BelongsTo;

/**
 * AI-3: one itinerary a user asked for, generated by GenerateItineraryPlan on the `itineraries` queue and kept
 * for "My plans". The reserved credit stays charged only for a plan with the AI narrative.
 */
class ItineraryPlan extends Model
{
    use HasUuids;

    public const STATUS_QUEUED = 'queued';
    public const STATUS_RUNNING = 'running';
    public const STATUS_DONE = 'done';
    public const STATUS_FAILED = 'failed';

    /** A plan running this long (worker --timeout is 4 min) or waiting this long in the queue is failed and its
     * credit given back. */
    public const STALE_RUNNING_MINUTES = 10;

    public const STALE_QUEUED_MINUTES = 30;

    protected $fillable = [
        'user_id', 'status', 'locale', 'country_code', 'duration_days', 'request', 'product_type', 'credit_charged',
        'title', 'result', 'error', 'started_at', 'finished_at',
    ];

    protected function casts(): array
    {
        return [
            'request' => 'array',
            'result' => 'array',
            'credit_charged' => 'boolean',
            'duration_days' => 'integer',
            'started_at' => 'datetime',
            'finished_at' => 'datetime',
        ];
    }

    public function user(): BelongsTo
    {
        return $this->belongsTo(User::class);
    }

    public function isFinished(): bool
    {
        return in_array($this->status, [self::STATUS_DONE, self::STATUS_FAILED], true);
    }
}
